public class UserProfile {
    private String username;
    private int age;

    public UserProfile(String username) {
        this(username, 18); // Constructor chaining
    }

    public UserProfile(String username, int age) {
        this.username = username; // Resolving shadowing
        this.age = age;
    }

    public UserProfile setAge(int age) {
        this.age = age;
        return this; // Fluent API support
    }
}
